"Your backup code":"Dein Backup-Code",
"Your data is now backed up automatically every day. If you ever get a new phone, this code brings everything back.":"Deine Daten werden jetzt jeden Tag automatisch gesichert. Wenn du ein neues Handy bekommst, holt dieser Code alles zurück.",
"Keep this code safe, e.g. in your Notes or as a screenshot. Without it the backup can't be opened.":"Bewahre diesen Code sicher auf, z. B. in deinen Notizen oder als Screenshot. Ohne ihn kann das Backup nicht geöffnet werden.",
"Restore from backup":"Aus Backup wiederherstellen",
"Enter your backup code. Your meals, weights, goals, meal plans and coach chat come back. Meal photos are not part of the backup.":"Gib deinen Backup-Code ein. Deine Mahlzeiten, Gewichte, Ziele, Essenspläne und der Coach-Chat kommen zurück. Essensfotos sind nicht im Backup.",
