"Automatic backup":"Automatisches Backup",
"Once a day your data is saved encrypted. With your backup code you get everything back, e.g. on a new phone.":"Einmal am Tag werden deine Daten verschlüsselt gesichert. Mit deinem Backup-Code bekommst du alles zurück, z. B. auf einem neuen Handy.",
