"At least 8 characters":"Al menos 8 caracteres",
"Create account":"Crear cuenta",
"Your iPhone can save the password for you. Without the password the data can't be opened, not even by us.":"Tu iPhone puede guardar la contraseña por ti. Sin la contraseña no se pueden abrir los datos, ni siquiera nosotros.",
"Already have an account? Sign in":"¿Ya tienes cuenta? Inicia sesión",
"New here? Create an account":"¿Eres nuevo? Crea una cuenta",
"Please enter a valid email.":"Introduce un email válido.",
