"Restore failed. Check your internet and try again.":"Herstellen mislukt. Controleer je internet en probeer het opnieuw.",
"Your backup code":"Je back-upcode",
"Your data is now backed up automatically every day. If you ever get a new phone, this code brings everything back.":"Je gegevens worden nu elke dag automatisch opgeslagen. Krijg je ooit een nieuwe telefoon, dan haalt deze code alles terug.",
"Keep this code safe, e.g. in your Notes or as a screenshot. Without it the backup can't be opened.":"Bewaar deze code goed, bijv. in je Notities of als screenshot. Zonder code kan de back-up niet geopend worden.",
"Restore from backup":"Herstellen vanaf back-up",
"Enter your backup code. Your meals, weights, goals, meal plans and coach chat come back. Meal photos are not part of the backup.":"Voer je back-upcode in. Je maaltijden, gewicht, doelen, maaltijdplannen en coachchat komen terug. Maaltijdfoto's zitten niet in de back-up.",
"Restore":"Herstellen",
"The code has 16 letters and numbers.":"De code heeft 16 letters en cijfers.",
"Restoring…":"Bezig met herstellen…",
"Replace the data on this phone with the backup?":"De gegevens op deze telefoon vervangen door de back-up?",
"Automatic backup":"Automatische back-up",
"Once a day your data is saved encrypted. With your backup code you get everything back, e.g. on a new phone.":"Eén keer per dag worden je gegevens versleuteld opgeslagen. Met je back-upcode krijg je alles terug, bijv. op een nieuwe telefoon.",
