"Restore failed. Check your internet and try again.":"Не удалось восстановить. Проверь интернет и попробуй ещё раз.",
"Your backup code":"Твой код резервной копии",
"Your data is now backed up automatically every day. If you ever get a new phone, this code brings everything back.":"Теперь твои данные автоматически сохраняются каждый день. Если сменишь телефон, этот код всё вернёт.",
"Keep this code safe, e.g. in your Notes or as a screenshot. Without it the backup can't be opened.":"Храни этот код в надёжном месте, например в Заметках или на скриншоте. Без него копию не открыть.",
"Restore from backup":"Восстановить из копии",
"Enter your backup code. Your meals, weights, goals, meal plans and coach chat come back. Meal photos are not part of the backup.":"Введи код копии. Вернутся блюда, вес, цели, планы питания и чат с коучем. Фото блюд в копию не входят.",
"Restore":"Восстановить",
"The code has 16 letters and numbers.":"В коде 16 букв и цифр.",
"Restoring…":"Восстановление…",
"Replace the data on this phone with the backup?":"Заменить данные на этом телефоне копией?",
"Automatic backup":"Автоматическое резервное копирование",
"Once a day your data is saved encrypted. With your backup code you get everything back, e.g. on a new phone.":"Раз в день твои данные сохраняются в зашифрованном виде. С кодом ты вернёшь всё, например на новом телефоне.",
