"Your backup code":"你的备份代码",
"Your data is now backed up automatically every day. If you ever get a new phone, this code brings everything back.":"你的数据现在每天自动备份。如果你换了新手机，这个代码可以找回一切。",
"Keep this code safe, e.g. in your Notes or as a screenshot. Without it the backup can't be opened.":"请妥善保存此代码，例如存在备忘录里或截图。没有它就无法打开备份。",
"Restore from backup":"从备份恢复",
"Enter your backup code. Your meals, weights, goals, meal plans and coach chat come back. Meal photos are not part of the backup.":"输入你的备份代码。你的餐食、体重、目标、饮食计划和教练聊天都会恢复。餐食照片不在备份中。",
